const filterEvents = (startDate, endDate) => {
  return EVENTS.filter((event) => {
    const eventStartDate = new Date(event.startDate);
    const eventEndDate = new Date(event.endDate);
    return (
      (eventStartDate >= startDate && eventStartDate <= endDate) ||
      (eventEndDate >= startDate && eventEndDate <= endDate)
    );
  });
};

export default function Scheduler({ externalDummyData }) {
  const schedulerRef = useRef(null);

  const [eventStore, setEventStore] = useState({
    lazyLoad: true,
    requestData: async ({ startDate, endDate }) => {
      return { success: true, data: [] };
    },
  });
  const [resourceStore, setResourceStore] = useState({
    autoLoad: true,
    requestData: async () => {
      console.log("requestData from resourceStore");
      const resources = generateResources();
      return { success: true, data: resources };
    },
  });
  // Internal dummy var
  const [dummy, setDummy] = useState(false);

  useEffect(() => {
    console.log("Dummy var changed", dummy);
  }, [dummy]);

  useEffect(() => {
    console.log("External dummy data changed", externalDummyData);
  }, [externalDummyData]);

  return (
    <>
      <BryntumScheduler
        ref={schedulerRef}
        columns={[
          {
            type: "resourceInfo",
            text: "Name",
            field: "name",
            width: 180,
            showImage: false,
          },
        ]}
        // Data
        eventStore={eventStore}
        resourceStore={resourceStore}
        //Default settings
        // visibleDate={{
        //   date: new Date(), // Today
        //   block: "center",
        // }}
        viewPreset="hourAndDay" // 1hour tick
        minZoomLevel={12} // 1day tick
        maxZoomLevel={20} // 5min tick
        infiniteScroll={true}
        minDate={new Date(new Date().setDate(new Date().getDate() - 1))}
        maxDate={
          new Date(new Date().setFullYear(new Date().getFullYear() + 30))
        }
        //Disabled features
        dependencyEditFeature={false}
        eventDragCreateFeature={false}
        eventDragSelectFeature={false}
        dependenciesFeature={{
          allowCreate: false,
        }}
        scheduleMenuFeature={false}
        cellMenuFeature={false}
        headerMenuFeature={false}
        //Enabled features
        eventMenuFeature={{
          items: {
            editEvent: false,
            deleteEvent: false,
            copyEvent: false,
            cutEvent: false,
          },
        }}
        timeRangesFeature={{
          showCurrentTimeLine: true,
          showHeaderElements: false,
        }}
        timeAxisHeaderMenuFeature={{
          items: {
            zoomLevel: false,
            dateRange: true,
            currentTimeLine: false,
          },
        }}
        //Toolbar
        tbar={[
          {
            type: "button",
            text: "Toogle useState",
            onClick: () => {
              setDummy(!dummy);
            },
          },
        ]}
      />
    </>
  );
}
